import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"; import { useState } from "react"; import { ActivityIndicator, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard"; import { Screen } from "../../ui/Screen"; import { colors, radius, spacing } from "../../ui/tokens"; import { firebaseAuth } from "../auth/firebase"; import { createVendorVoucher, getVendorReport, getVendorReturns, getVendorStaff, getVendorVouchers, updateVendorStaff } from "./vendor.api";
export function VendorOperationsScreen() { const user = firebaseAuth?.currentUser ?? null; const queryClient = useQueryClient(); const report = useQuery({ queryKey: ["vendor", "report"], queryFn: () => getVendorReport(user!), enabled: Boolean(user) }); const returns = useQuery({ queryKey: ["vendor", "returns"], queryFn: () => getVendorReturns(user!), enabled: Boolean(user) }); const staff = useQuery({ queryKey: ["vendor", "staff"], queryFn: () => getVendorStaff(user!), enabled: Boolean(user) }); const vouchers = useQuery({ queryKey: ["vendor", "vouchers"], queryFn: () => getVendorVouchers(user!), enabled: Boolean(user) }); const [voucher, setVoucher] = useState({ code: "", value: "10" }); const saveVoucher = useMutation({ mutationFn: () => { const startsAt = new Date(); const endsAt = new Date(startsAt.getTime() + 30 * 24 * 60 * 60_000); return createVendorVoucher(user!, { code: voucher.code, discountType: "PERCENT", value: Number(voucher.value), startsAt: startsAt.toISOString(), endsAt: endsAt.toISOString() }); }, onSuccess: () => { setVoucher({ code: "", value: "10" }); return queryClient.invalidateQueries({ queryKey: ["vendor", "vouchers"] }); } }); const staffStatus = useMutation({ mutationFn: ({ id, status, permissions }: { id: string; status: "active" | "suspended"; permissions: Array<"orders:read" | "orders:manage" | "products:manage" | "inventory:manage" | "finance:read" | "support:manage"> }) => updateVendorStaff(user!, id, { status, permissions }), onSuccess: () => queryClient.invalidateQueries({ queryKey: ["vendor", "staff"] }) }); return <Screen eyebrow="SELLER CENTER" title="Business operations" description="Live reports, customer returns, staff access, and seller-funded vouchers.">{report.isLoading ? <ActivityIndicator color={colors.primary} /> : null}{report.data ? <View style={styles.metrics}><Metric label="Orders" value={report.data.orderCount} /><Metric label="Delivered" value={report.data.deliveredCount} /><Metric label="Products" value={report.data.productCount} /><Metric label="Low stock" value={report.data.lowStockCount} /></View> : null}{report.data ? <ModuleCard title={`৳${(Number(report.data.grossSalesMinor) / 100).toLocaleString("en-BD")}`} meta="Delivered gross sales"><Text style={styles.muted}>{Object.entries(report.data.statusCounts).map(([status, count]) => `${status}: ${count}`).join(" · ")}</Text></ModuleCard> : null}<Text style={styles.heading}>Returns</Text>{returns.data?.map((item) => <ModuleCard key={item.id} title={item.reasonCode} meta={`${item.status} · ৳${(Number(item.requestedAmount.amountMinor) / 100).toLocaleString("en-BD")}`}><Text style={styles.muted}>{item.items.length} item(s) · order {item.orderId.slice(0, 8)}</Text></ModuleCard>)}{returns.data?.length === 0 ? <ModuleCard title="No seller returns" meta="Customer return requests will appear here." /> : null}<Text style={styles.heading}>Vouchers</Text><ModuleCard title="Create 30-day voucher"><View style={styles.row}><TextInput onChangeText={(code) => setVoucher({ ...voucher, code })} placeholder="CODE" placeholderTextColor={colors.muted} style={styles.input} value={voucher.code} /><TextInput keyboardType="numeric" onChangeText={(value) => setVoucher({ ...voucher, value })} placeholder="%" placeholderTextColor={colors.muted} style={styles.smallInput} value={voucher.value} /><Pressable disabled={saveVoucher.isPending || voucher.code.length < 3} onPress={() => saveVoucher.mutate()} style={styles.button}><Text style={styles.buttonText}>Create</Text></Pressable></View></ModuleCard>{vouchers.data?.map((item) => <ModuleCard key={item.id} title={item.code} meta={`${item.active ? "ACTIVE" : "INACTIVE"} · ends ${new Date(item.endsAt).toLocaleDateString()}`}><Text style={styles.muted}>{JSON.stringify(item.rules)}</Text></ModuleCard>)}<Text style={styles.heading}>Staff access</Text>{staff.data?.map((member) => <ModuleCard key={member.id} title={member.displayName || member.email || "Vendor member"} meta={`${member.role} · ${member.status}`}><Text style={styles.muted}>{member.permissions.join(", ") || "No delegated permissions"}</Text>{member.role !== "VENDOR_OWNER" ? <Pressable onPress={() => staffStatus.mutate({ id: member.id, status: member.status === "active" ? "suspended" : "active", permissions: member.permissions.filter((permission): permission is "orders:read" | "orders:manage" | "products:manage" | "inventory:manage" | "finance:read" | "support:manage" => ["orders:read", "orders:manage", "products:manage", "inventory:manage", "finance:read", "support:manage"].includes(permission)) })} style={styles.outline}><Text style={styles.outlineText}>{member.status === "active" ? "Suspend access" : "Restore access"}</Text></Pressable> : null}</ModuleCard>)}</Screen>; }
function Metric({ label, value }: { label: string; value: number }) { return <View style={styles.metric}><Text style={styles.metricValue}>{value}</Text><Text style={styles.muted}>{label}</Text></View>; }
const styles = StyleSheet.create({ metrics: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, metric: { backgroundColor: colors.primarySoft, borderRadius: radius.lg, flex: 1, minWidth: 90, padding: spacing.md }, metricValue: { color: colors.primary, fontSize: 25, fontWeight: "700" }, heading: { color: colors.text, fontSize: 21, fontWeight: "700" }, muted: { color: colors.muted, fontSize: 12, lineHeight: 18 }, row: { flexDirection: "row", gap: spacing.sm }, input: { borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, flex: 1, minHeight: 44, paddingHorizontal: 10 }, smallInput: { borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, minHeight: 44, paddingHorizontal: 10, width: 65 }, button: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", paddingHorizontal: spacing.md }, buttonText: { color: "#fff", fontWeight: "700" }, outline: { alignItems: "center", borderColor: colors.danger, borderRadius: radius.md, borderWidth: 1, minHeight: 42, justifyContent: "center" }, outlineText: { color: colors.danger, fontWeight: "700" } });
